const response = $input.first().json;
const jobs = response.jobs_results || [];

// Agrégateurs : utilisables mais en dernier recours.
// On préfère le site carrière / ATS de l'entreprise (aide aussi Claude à trouver le domaine).
const AGREGATEURS = [
  'indeed', 'linkedin', 'glassdoor', 'jooble', 'talent.com', 'hellowork',
  'monster', 'ziprecruiter', 'neuvoo', 'jobijoba', 'optioncarriere',
  'meteojob', 'cadremploi', 'apec', 'france travail', 'pôle emploi',
  'trovit', 'careerjet', 'adzuna', 'jobrapido', 'emploi.org'
];

function cleanUrl(u) {
  if (!u) return '';
  try {
    const url = new URL(u);
    // enlève le tracking google_jobs_apply
    ['utm_campaign', 'utm_source', 'utm_medium', 'utm_content', 'utm_term', 'gh_src']
      .forEach(p => url.searchParams.delete(p));
    return url.toString();
  } catch (e) {
    return u;
  }
}

function pickUrl(job) {
  const opts = Array.isArray(job.apply_options) ? job.apply_options : [];
  const valides = opts.filter(o => o && o.link);

  if (valides.length) {
    const estAgregateur = o =>
      AGREGATEURS.some(a => String(o.title || '').toLowerCase().includes(a));

    // 1er choix : lien direct employeur / ATS
    const direct = valides.find(o => !estAgregateur(o));
    if (direct) return cleanUrl(direct.link);

    // 2e choix : premier agrégateur dispo
    return cleanUrl(valides[0].link);
  }

  // 3e choix : lien de secours qui fonctionne TOUJOURS (recherche ciblée)
  const q = [job.company_name, job.title].filter(Boolean).join(' ');
  if (q) {
    return 'https://www.google.com/search?q=' + encodeURIComponent(q) + '&gl=fr&hl=fr';
  }
  return '';
}

return jobs.map(job => ({
  json: {
    id: job.job_id || '',
    intitule: job.title || '',
    entreprise: job.company_name || '',
    typeContrat: job.detected_extensions?.schedule_type || '',
    codePostal: job.location || '',
    lieu: job.location || '',
    salaire: job.detected_extensions?.salary || '',
    description: job.description || '',
    experience: job.job_highlights?.find(h => h.title === 'Qualifications')?.items?.[0] || '',
    nombrePostes: 1,
    source: job.via || '',
    romeLibelle: job.title || '',
    dateCreation: job.detected_extensions?.posted_at || '',   // 👈 voir note plus bas
    motsCles: job.extensions?.join(', ') || '',
    url: pickUrl(job),
    urlGoogle: job.share_link || '',   // conservé pour debug, pas écrit dans Excel
    thumbnail: job.thumbnail || ''
  }
}));

function normalizeDomain(url) {
  if (!url) return "";
  let d = String(url).toLowerCase().trim();
  d = d.replace(/^https?:\/\//, "")
       .replace(/^www\./, "")
       .split(/[\/?#]/)[0]
       .trim();
  if (!d || !d.includes(".")) return "";
  const generiques = ["linkedin.com", "facebook.com", "pagesjaunes.fr", "societe.com", "indeed.com", "google.com", "hellowork.com"];
  if (generiques.some(g => d === g || d.endsWith("." + g))) return "";
  return d;
}

// --- Parsing de la réponse Claude ---
const content = $input.first().json.content;
const textBlocks = content.filter(c => c.type === 'text');
const allText = textBlocks.map(b => b.text).join(' ');

const cleaned = allText.replace(/```json/g, '').replace(/```/g, '');
const match = cleaned.match(/\{[^{}]*"pertinent"[^{}]*\}/);

const original = $('Loop Over Items4').last().json;

let result = { pertinent: false, raison: 'parse_error', secteur: 'NOT_FOUND', score: 0, classification: 'OUT' };
if (match) {
  try {
    result = JSON.parse(match[0]);
  } catch (e) {}
}

// Fallback : si tronqué mais classification visible dans le texte
if (result.raison === 'parse_error') {
  if (allText.includes('Classification → OUT') || allText.includes('classification": "OUT"')) {
    result = { pertinent: false, raison: 'ETT_concurrente', secteur: 'NOT_FOUND', score: 0, classification: 'OUT' };
  }
}

// --- Vérification : domaine déjà dans le Pipeline ---
// ⚠️ Le site web vient de la réponse Claude (result.site_web), pas de l'item original
const siteItem = normalizeDomain(
  result.site_web || result.siteWeb || result.domaine ||
  original.site_web || original.siteWeb || original.website || ''
);

if (siteItem) {
  const pipelineRows = $('Lire Pipeline2').all();
  for (const row of pipelineRows) {
    const sitePipeline = normalizeDomain(row.json.Domaine || '');
    if (sitePipeline && sitePipeline === siteItem) {
      result = {
        ...result,
        pertinent: false,
        raison: 'site_web_deja_existant',
        classification: 'OUT',
        score: 0
      };
      break;
    }
  }
}

return [{
  json: {
    ...original,
    ...result,
    _domaine: siteItem
  }
}];

const item = $json;
const people = item.people || [];
const score = item.score || '';
const secteur = item.secteur || '';
const domaine = $('Code in JavaScript7').last().json.site_web || item.domaine_extrait || item.domaine || '';
const classification = item.classification || '';
const entreprise = $('Loop Over Items4').last().json.entreprise || item.entreprise || '';
const urlOffre = $('Loop Over Items4').last().json.urlOffre || item.urlOffre || '';

if (people.length === 0) {
  return [{
    json: {
      person_id: null,
      first_name: null,
      last_name: null,
      title: null,
      linkedin_url: '',
      has_email: false,
      company: '',
      score: score,
      secteur: secteur,
      domaine: domaine,
      entreprise: entreprise,
      classification: classification,
      urlOffre: urlOffre,
      _no_leads: true
    }
  }];
}
$input.first().json.entreprise
return people.map(person => ({
  json: {
    person_id: person.id,
    first_name: person.first_name,
    last_name: person.last_name_obfuscated || person.last_name,
    title: person.title,
    linkedin_url: person.linkedin_url || '',
    has_email: person.has_email,
    company: person.organization?.name || '',   // 👈 entreprise actuelle du contact
    score: score,
    secteur: secteur,
    domaine: domaine,
    entreprise: entreprise,
    classification: classification,
    urlOffre: urlOffre
  }
}));

function normalizeCompany(name) {
  if (!name) return "";
  return name
    .toLowerCase()
    .replace(/\s+(sas|sarl|sa|sasu|eurl|sci|scop|eti|group|groupe)\b/g, "")
    .replace(/[^a-z0-9àâäéèêëïîôùûüÿçœæ]/g, "")
    .trim();
}
// Lire directement depuis les nodes Excel
const pipelineRows = $('Lire Pipeline2').all();
const rejeteRows = $('Lire rejetés').all();
const concurrentRows = $('Lire Concurrents').all();
const existingCompanies = new Set();
for (const row of pipelineRows) {
  const norm = normalizeCompany(row.json.Entreprise || '');
  if (norm) existingCompanies.add(norm);
}
for (const row of rejeteRows) {
  const norm = normalizeCompany(row.json.Company || '');
  if (norm) existingCompanies.add(norm);
}
for (const row of concurrentRows) {
  const norm = normalizeCompany(row.json.Entreprise || '');
  if (norm) existingCompanies.add(norm);
}
function isExisting(normName) {
  if (!normName) return false;
  if (existingCompanies.has(normName)) return true;
  for (const existing of existingCompanies) {
    if (normName.includes(existing) || existing.includes(normName)) return true;
  }
  return false;
}
const allOffres = $input.all();
if (!allOffres.length) {
  return [{ json: { _info: "aucun item en entrée" } }];
}
const seenIds = new Set();
const seenEntreprises = new Set();
const results = [];
for (const o of allOffres) {
  // Dédup par ID
  const offreId = o.json.id || '';
  if (offreId) {
    if (seenIds.has(offreId)) continue;
    seenIds.add(offreId);
  }
  // Dédup par entreprise
  const nom = o.json.entreprise || '';
  const norm = normalizeCompany(nom);
  if (!norm) continue;
  if (seenEntreprises.has(norm)) continue;
  seenEntreprises.add(norm);
  if (isExisting(norm)) continue;
  results.push({
    json: {
      id: o.json.id,
      intitule: o.json.intitule,
      entreprise: nom,
      typeContrat: o.json.typeContrat,
      lieu: o.json.lieu,
      codePostal: o.json.codePostal,
      salaire: o.json.salaire,
      description: o.json.description,
      experience: o.json.experience,
      nombrePostes: o.json.nombrePostes,
      romeCode: o.json.romeCode,
      romeLibelle: o.json.romeLibelle,
      dateCreation: o.json.dateCreation,
      urlOffre: o.json.urlOffre || o.json.url || '',
      motsCles: o.json.motsCles,
      _date_check: new Date().toISOString().split('T')[0]
    }
  });
}
if (!results.length) {
  return [{ json: { _info: "aucune nouvelle entreprise trouvée" } }];
}
return results;

const item = $json;
const people = item.people || [];
const domaine = $('Code in JavaScript7').last().json.site_web || item.domaine_extrait || item.domaine || '';
const entreprise = $('Loop Over Items4').last().json.entreprise || item.entreprise || '';
const urlOffre = $('Loop Over Items4').last().json.urlOffre || item.urlOffre || '';

if (people.length === 0) {
  return [{
    json: {
