      first_name: null,
      last_name: null,
      title: null,
      linkedin_url: '',
      has_email: false,
      company: '',
      domaine: domaine,
      entreprise: entreprise,
      classification: 'OUT',
      raison: 'ETT_concurrente',
      urlOffre: urlOffre,
      _no_leads: true
    }
  }];
}

return people.map(person => ({
  json: {
    person_id: person.id,
    first_name: person.first_name,
    last_name: person.last_name_obfuscated || person.last_name,
    title: person.title,
    linkedin_url: person.linkedin_url || '',
    has_email: person.has_email,
    company: person.organization?.name || '',
    domaine: domaine,
    entreprise: entreprise,
    classification: 'OUT',
    raison: 'ETT_concurrente',
    urlOffre: urlOffre
  }
}));
